package com.carebridge.backend.security;
import static org.junit.jupiter.api.Assertions.assertTrue;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;import com.carebridge.backend.common.config.JpaAuditingConfig;import com.carebridge.backend.config.MockMvcSecurityBuilderConfig;import com.carebridge.backend.partner.controller.PartnerPerformanceController;import com.carebridge.backend.partner.service.PartnerPerformanceService;import com.carebridge.backend.security.config.SecurityConfig;import com.carebridge.backend.security.jwt.JwtTokenProvider;import com.carebridge.backend.security.repository.UserRepository;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.*;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.web.bind.annotation.RequestMethod;import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;
@WebMvcTest(value=PartnerPerformanceController.class,excludeFilters=@ComponentScan.Filter(type=FilterType.ASSIGNABLE_TYPE,classes=JpaAuditingConfig.class))@Import({SecurityConfig.class,MockMvcSecurityBuilderConfig.class})class PartnerPerformanceControllerSecurityTest{@Autowired MockMvc mvc;@Autowired RequestMappingHandlerMapping mappings;@MockitoBean PartnerPerformanceService service;@MockitoBean JwtTokenProvider jwt;@MockitoBean UserRepository users;@Test @WithMockUser(roles="MOTHER")void ppfTc508_nonPartnerReturns403()throws Exception{mvc.perform(get("/api/v1/partner/performance")).andExpect(status().isForbidden());}@Test void ppfTc509_noJwtReturns401()throws Exception{assertTrue(mappings.getHandlerMethods().keySet().stream().anyMatch(i->i.getPatternValues().contains("/api/v1/partner/performance")&&i.getMethodsCondition().getMethods().contains(RequestMethod.GET)));mvc.perform(get("/api/v1/partner/performance")).andExpect(status().isUnauthorized());}}
